<script setup lang="ts">
import { ref,computed,h } from 'vue'
import { NConfigProvider, NMessageProvider, NLayout, NLayoutHeader, NLayoutSider, NLayoutContent, NMenu, NRadioGroup, NRadioButton,NInput } from 'naive-ui'
import { useRouter } from 'vue-router'
import {useProject} from './project'
import ProjectToolbar from './ProjectToolbar.vue'
import {tableCatalog} from './tableCatalog'
const router = useRouter(),project=useProject()
const mode=ref('Table'),navSearch=ref('')
const names=["AttackSEMessage", "BingoMissionConditionMessage", "BingoMissionMessage", "BoostItemMessage", "Chara01Message", "Chara02Message", "Chara03Message", "Chara04Message", "Chara54Message", "Chara55Message", "Chara56Message", "Chara57Message", "Chara58Message", "Chara59Message", "Chara60Message", "Chara61Message", "CharaMessageCommon", "ErrorMessage", "EventMessage", "GradeMessage", "IconMessage", "MultiPlayMessage", "MusicLicenseMessage", "MusicSearchMessage", "MusicSelectOptionMenuMessage", "MyRoomMessage", "NavigateCharacterMessage", "NGWordMessage", "ResultMessage", "ShopMessage", "StageUpMessage", "SugorokuMessage", "SystemMessage", "TestModeMessage", "TicketMessage", "TouchEffectMessage", "TouchPanelSymbolColorMessage", "UserPlateBackgroundMessage", "WelcomeMessage"]
const messageLabels:Record<string,string>={"AttackSEMessage": "打击音效", "BingoMissionConditionMessage": "宾果任务条件", "BingoMissionMessage": "宾果任务", "BoostItemMessage": "增益道具", "Chara01Message": "角色 01", "Chara02Message": "角色 02", "Chara03Message": "角色 03", "Chara04Message": "角色 04", "Chara54Message": "角色 54", "Chara55Message": "角色 55", "Chara56Message": "角色 56", "Chara57Message": "角色 57", "Chara58Message": "角色 58", "Chara59Message": "角色 59", "Chara60Message": "角色 60", "Chara61Message": "角色 61", "CharaMessageCommon": "角色通用", "ErrorMessage": "错误信息", "EventMessage": "活动", "GradeMessage": "等级", "IconMessage": "图标", "MultiPlayMessage": "多人游玩", "MusicLicenseMessage": "歌曲版权", "MusicSearchMessage": "歌曲搜索", "MusicSelectOptionMenuMessage": "选曲设置菜单", "MyRoomMessage": "个人房间", "NavigateCharacterMessage": "导航角色", "NGWordMessage": "禁用词", "ResultMessage": "成绩结果", "ShopMessage": "商店", "StageUpMessage": "段位挑战", "SugorokuMessage": "双六", "SystemMessage": "系统", "TestModeMessage": "测试模式", "TicketMessage": "票券", "TouchEffectMessage": "触摸特效", "TouchPanelSymbolColorMessage": "触摸符号颜色", "UserPlateBackgroundMessage": "玩家名牌背景", "WelcomeMessage": "欢迎信息"}
function navLabel(chinese:string,english:string){return ()=>h('div',{class:'nav-label'},[h('div',chinese),h('small',english)])}
const options=computed(()=>mode.value==='Table'?[...new Set(tableCatalog.map(t=>t.group))].map(group=>({key:group,label:group,children:tableCatalog.filter(t=>t.group===group&&`${t.title} ${t.name}`.toLowerCase().includes(navSearch.value.toLowerCase())).map(({name,title})=>({label:navLabel(title,name),key:'/table/'+name}))})).filter(g=>g.children.length):names.filter(name=>`${messageLabels[name]} ${name}`.toLowerCase().includes(navSearch.value.toLowerCase())).map(name=>({label:navLabel(messageLabels[name]??name,name),key:'/message/'+encodeURIComponent(name)})))
function toggle(value:string){mode.value=value;router.push(value==='Table'?'/table/MusicParameterTable':names.length?'/message/'+encodeURIComponent(names[0]!):'/message')}
</script>
<template><n-config-provider><n-message-provider><n-layout style="height:100vh"><n-layout-header bordered><project-toolbar /></n-layout-header><n-layout has-sider style="height:calc(100vh - 54px)"><n-layout-sider bordered :width="245" content-style="overflow:auto"><div style="padding:16px"><n-radio-group :value="mode" @update:value="toggle"><n-radio-button value="Table">Table</n-radio-button><n-radio-button value="Message">Message</n-radio-button></n-radio-group><n-input v-model:value="navSearch" placeholder="搜索表 / Table" clearable size="small" style="margin-top:10px"/></div><n-menu :options="options" :value="router.currentRoute.value.path" @update:value="router.push" /></n-layout-sider><n-layout-content content-style="padding:12px 16px"><router-view :key="project.id + router.currentRoute.value.fullPath" /></n-layout-content></n-layout></n-layout></n-message-provider></n-config-provider></template>
<style>body{margin:0;font-family:system-ui,sans-serif}*{box-sizing:border-box}.page-title{font-size:18px;line-height:24px;margin:0 0 8px;font-weight:600}.nav-label{line-height:20px;padding:5px 0}.nav-label small{display:block;color:#888;font-size:11px}.n-menu .n-menu-item{height:54px}</style>
